-- Check if panel.panemark matches performance.solmodref and environment.arearegistry matches plant.growregistry
SELECT COUNT(*) AS matching_perf FROM panel p JOIN performance pr ON p.panemark = pr.solmodref;
SELECT COUNT(*) AS matching_env FROM panel p JOIN environment e ON p.hubregistry = e.arearegistry;

SELECT ROUND(AVG(
  CAST(pr.efficiency_profile->'current_efficiency'->>'curreffpct' AS numeric) * (1 + p.tempcoef * (25 - e.celltempc) / 100) * (1000 / CAST((e.irradiance_conditions->'irradiance_types')->>3 AS numeric))
), 2) AS avg_wce
FROM panel p
JOIN environment e ON p.hubregistry = e.arearegistry
JOIN performance pr ON p.panemark = pr.solmodref;

SELECT ROUND(AVG(
  CAST(pr.efficiency_profile->'current_efficiency'->>'curreffpct' AS numeric) * (1 + p.tempcoef * (25 - e.celltempc) / 100) * (1000 / CAST((e.irradiance_conditions->'irradiance_types')->>3 AS numeric))
), 2) AS avg_wce
FROM panel p
JOIN environment e ON p.hubregistry = e.arearegistry
JOIN performance pr ON p.panemark = pr.solmodref;
